const data = $input.first().json.data;

const parsed = typeof data === 'string'
  ? JSON.parse(data)
  : data;

return [
  {
    json: parsed
  }
];

const data = $input.first().json;

const incidents = data.incidents || [];

const unique = [];
const seen = new Set();

for (const incident of incidents) {
  const key = [
    incident.pod,
    incident.container,
    incident.severity,
    incident.message
  ].join('|');

  if (!seen.has(key)) {
    seen.add(key);
    unique.push(incident);
  }
}

return [
  {
    json: {
      ...data,
      incidents: unique,
      incident_count: unique.length
    }
  }
];

const items = $input.all();

const incidentsByResource = new Map();

for (const item of items) {
  const incident = item.json;

  const key = [
    incident.cluster,
    incident.namespace,
    incident.pod,
    incident.container,
  ].join("|");

  if (!incidentsByResource.has(key)) {
    incidentsByResource.set(key, {
      cluster: incident.cluster,
      namespace: incident.namespace,
      pod: incident.pod,
      container: incident.container,
      node: incident.node,
      pod_ip: incident.pod_ip,
      image: incident.image,

      highest_severity: incident.severity,

      timestamps: [],
      messages: [],
      evidence: [],
    });
  }

  const grouped = incidentsByResource.get(key);

  if (incident.timestamp) {
    grouped.timestamps.push(incident.timestamp);
  }

  if (incident.message) {
    grouped.messages.push(incident.message);
  }

  grouped.evidence.push({
    timestamp: incident.timestamp,
    severity: incident.severity,
    message: incident.message,
  });

  // Promote severity if a CRITICAL record is present.
  if (incident.severity === "CRITICAL") {
    grouped.highest_severity = "CRITICAL";
  }
}

return Array.from(incidentsByResource.values()).map((incident) => ({
  json: {
    incident: {
      cluster: incident.cluster,
      namespace: incident.namespace,
      pod: incident.pod,
      container: incident.container,
      node: incident.node,
      pod_ip: incident.pod_ip,
      image: incident.image,
      severity: incident.highest_severity,
      timestamps: incident.timestamps,
      messages: [...new Set(incident.messages)],
      evidence: incident.evidence,
    }
  }
}));

const kubernetes = $input.first().json;

const normalized = $('Normalize / Aggregate Incident').first().json;

return [
  {
    json: {
      incident: normalized.incident,
      kubernetes: kubernetes
    }
  }
];

