parameters.jsCode:
const incident = $json.incident;
const resource = $json.resource;

const escapeHtml = (value) =>
  String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

const observations = ($json.observations || [])
  .map(item => `<li>${escapeHtml(item)}</li>`)
  .join("");

const evidence = ($json.evidence || [])
  .map(item => `<li>${escapeHtml(item)}</li>`)
  .join("");

const causes = ($json.probable_causes || [])
  .map(item => `
    <li>
      <strong>${escapeHtml(item.cause)}</strong>
      — Likelihood: ${escapeHtml(item.likelihood)}
      <br>
      ${escapeHtml(item.reason)}
    </li>
  `)
  .join("");

const actions = ($json.recommended_actions || [])
  .map(item => `
    <li>
      <strong>Priority ${escapeHtml(item.priority)}:</strong>
      ${escapeHtml(item.action)}
      <br>
      <strong>Risk:</strong> ${escapeHtml(item.risk)}
      ${item.command
        ? `<br><strong>Command:</strong> <code>${escapeHtml(item.command)}</code>`
        : ""}
    </li>
  `)
  .join("");

const investigation = ($json.investigation_commands || [])
  .map(item => `<li><code>${escapeHtml(item)}</code></li>`)
  .join("");

const html = `
<html>
<body style="font-family: Arial, sans-serif; line-height: 1.5;">

<h2>🚨 Kubernetes Critical Incident</h2>

<p>
<strong>Severity:</strong> ${escapeHtml(incident.severity)}<br>
<strong>Confidence:</strong> ${escapeHtml(incident.confidence)}%
</p>

<h3>${escapeHtml(incident.title)}</h3>

<p>
<strong>Category:</strong> ${escapeHtml(incident.category)}
</p>

<h3>Resource</h3>

<ul>
<li><strong>Cluster:</strong> ${escapeHtml(resource.cluster)}</li>
<li><strong>Namespace:</strong> ${escapeHtml(resource.namespace)}</li>
<li><strong>Pod:</strong> ${escapeHtml(resource.pod)}</li>
<li><strong>Container:</strong> ${escapeHtml(resource.container)}</li>
<li><strong>Node:</strong> ${escapeHtml(resource.node)}</li>
</ul>

<h3>Summary</h3>

<p>${escapeHtml($json.summary)}</p>

<h3>Observed Facts</h3>

<ul>
${observations}
</ul>

<h3>Evidence</h3>

<ul>
${evidence}
</ul>

<h3>Probable Causes</h3>

<ul>
${causes}
</ul>

<h3>Recommended Actions</h3>

<ul>
${actions}
</ul>

<h3>Investigation Commands</h3>

<ul>
${investigation}
</ul>

<hr>

<p style="font-size: 12px; color: #666;">
Generated automatically by the AWS EKS AI Incident Analysis workflow.
</p>

</body>
</html>
`;

return {
  json: {
    ...$json,
    email_subject: `[${incident.severity}] ${incident.title}`,
    email_html: html
  }
};
